#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-2.0-only
# ZINE in FS-UAE (DESIGN D29 sections 15 and 16): step 2, the kernel's pause and resume with the null blob
# (/tests/zine/null.blob: back at once through the resume routine), once and then twenty times in a row in a script,
# and Zenix as before afterwards: the memory (as after the first run), the console's input (CON_INPUT), a file written
# and read back. zine runs only at the Amiga's own console: the serial line's input is the shown console's (kernel/tty.c).
cd "$(dirname "$0")/.." || exit 1
BD=${ZENIX_BUILD:-build}
make -s BUILD=$BD all >/dev/null 2>&1 || { echo "build failed"; exit 1; }
rm -f $BD/zenix.hdf; make -s BUILD=$BD $BD/zenix.hdf >/dev/null 2>&1
OUT=${ZENIX_OUT:-/tmp/zenix-zine}; mkdir -p $OUT
ZENIX_BUILD=$BD tools/run-test.sh fsuae/a1200-020-fast.fs-uae 400 tools/tests/zine-null-test.txt > $OUT/serial.log 2>&1
L=$OUT/serial.log
pass=1
ok() { echo "PASS $1"; }
no() { echo "FAIL $1"; pass=0; }
log=$(tr -d '\r' < $L)
n=$(echo "$log" | grep -ac '^zine: back after [0-9]* s (0)')
[ "$n" = 57 ] && ok "every session came back (the kernel's 'back' line 57 times)" || no "the kernel's 'back' line $n times, not 57 (21 null sessions; zexit, the long name, zhello, ztake, zcrash, zbadcall, zalloc twice, zscreen, zovl twice, zpkt twice, zcrunch, zsuper, zcalls, zbig twice, zhello -c, zlean, the Latin-1 name, znext, zlibs, zwrite, zcase, zexec, zmmu, zfpu; ztake with the background writer; three by name; the group member twice; ztask, zsound)"
echo "$log" | grep -aq '^count=20 ok=20' && ok "the console's shell ran zine twenty times and went on" || no "the console's loop: $(echo "$log" | grep -a '^count=')"
f1=$(echo "$log" | grep -a -m1 '^fast RAM free' | tr -dc 0-9); f2=$(echo "$log" | grep -a '^fast RAM free' | sed -n 2p | tr -dc 0-9)
c1=$(echo "$log" | grep -a -m1 '^chip RAM free' | tr -dc 0-9); c2=$(echo "$log" | grep -a '^chip RAM free' | sed -n 2p | tr -dc 0-9)
[ -n "$f1" ] && [ "$f1" = "$f2" ] && [ "$c1" = "$c2" ] && ok "free memory after twenty more sessions as after the first (chip $c1 KB, fast $f1 KB)" \
    || no "free memory changed: chip $c1 -> $c2 KB, fast $f1 -> $f2 KB"
echo "$log" | grep -aq '^typed-after' && ok "the console takes input afterwards" || no "the console's input afterwards"
echo "$log" | grep -aq '^disk-ok' && ok "a file written and read back afterwards" || no "the disk afterwards"
# step 3, the real blob (/lib/zine/zine.blob) with the test programs, AmigaOS hunk executables written for the purpose
echo "$log" | grep -aq '^zexit-rc=7' && echo "$log" | grep -aq 'zexit ended (return code 7)' && ok "zexit: an AmigaOS program ran and returned 7" || no "zexit: $(echo "$log" | grep -a 'zexit' | tail -2)"
echo "$log" | grep -aq '^zlong-rc=7' && ok "a program whose name is longer than 31 bytes (the owner's Desire-BaconOfHope-HDVersion.exe)" || no "a long name: $(echo "$log" | grep -a 'zexit-with' | tail -2)"
echo "$log" | grep -aq '^hello from an AmigaOS program' && echo "$log" | grep -aq '^zhello-rc=0' && ok "zhello: dos.library's Output() and Write(), the text shown after" || no "zhello: $(echo "$log" | grep -a 'zhello' | tail -2)"
echo "$log" | grep -aq 'ztake ended (return code 0) after [2-4] s' && echo "$log" | grep -aq '^ztake-rc=0' && ok "ztake: its own Copper list for 150 frames, the display given back" || no "ztake: $(echo "$log" | grep -a 'ztake' | tail -2)"
echo "$log" | grep -aq 'zcrash crashed: illegal instruction at' && echo "$log" | grep -aq '^zcrash-rc=1' && ok "zcrash: an illegal instruction is reported, Zenix is back" || no "zcrash: $(echo "$log" | grep -a 'zcrash' | tail -2)"
echo "$log" | grep -aq 'zbadcall called exec.library AddSemaphore (offset -600, from' && ok "zbadcall: a call ZINE lacks is named, the program stopped" || no "zbadcall: $(echo "$log" | grep -a 'zbadcall' | tail -2)"
echo "$log" | grep -aq '^zalloc-rc=0' && ok "zalloc: 1 MB fast and 256 KB chip from AllocMem, written and read back, freed; a pool: two small blocks next to each other in one puddle (no bookkeeping between them, a write before the second harmless), a big one apart, freed, DeletePool (16.22); AvailMem as before" || no "zalloc: $(echo "$log" | grep -a 'zalloc' | tail -2)"
# zalloc b runs after the last memory reading: one more command line there grew the shell's own heap by 6 KB (its history), not ZINE's memory (round 13)
echo "$log" | grep -aq '^ZINE: FreeMem of 00000040 bytes at 00f80000, in no memory list' && echo "$log" | grep -aq 'zalloc crashed (alert 8100000f)' && echo "$log" | grep -aq '^zallocb-rc=1' && ok "zalloc b: a FreeMem of a block in no memory list named (size and address, 16.22), exec's AN_BadFreeAddr ends it" || no "zalloc b: $(echo "$log" | grep -a 'FreeMem of\|zalloc' | tail -3)"
echo "$log" | grep -aq '^zscreen-rc=0' && ok "zscreen: an 8-plane screen from intuition, LoadRGB32's colours, a user Copper list on its ViewPort (its MOVE seen in DMACONR, gone after FreeVPortCopLists; 16.18), a sprite from AllocSpriteDataA as sprite 2, moved by MoveSprite (its control words, the hardware's collision with plane 1 seen only while it is shown; 16.19), CloseScreen" || no "zscreen: $(echo "$log" | grep -a 'zscreen' | tail -2)"
# 16.6: an overlaid program: its root loaded with the overlay handle and tables, two nodes through its own overlay
# supervisor (Seek, LoadSeg(NULL, table, handle)), one replacing the other, the data after the nodes read through the
# handle; then an overlay entry with no node behind it: LoadSeg's refusal named and the supervisor's alert
echo "$log" | grep -aq '^ZINE: zovl is overlaid: 2 later parts' && ok "zovl: zine sees an overlaid program (2 later parts)" || no "zovl: zine's overlay line: $(echo "$log" | grep -a 'zovl is' | tail -1)"
echo "$log" | grep -aq '^zovl: LoadSeg wrote the overlay handle, the overlay table and the hunk table into the root' && ok "zovl: LoadSeg wrote the overlay handle and both tables into the root's overlay header" || no "zovl: the overlay header: $(echo "$log" | grep -a '^zovl' | head -2)"
na=$(echo "$log" | grep -ac "^zovl: node A ran; the root's data says: hello from the root's data hunk$")
[ "$na" = 2 ] && ok "zovl: node A ran twice (loaded, replaced by B, loaded again), relocated to itself and to the root's data hunk" || no "zovl: node A's line $na times, not 2"
echo "$log" | grep -aq '^zovl: node B ran; its BSS hunk was clear$' && echo "$log" | grep -aq "^zovl: node B's BSS slot cleared when A came back" && ok "zovl: node B ran in A's place (its code and chip BSS), its slot cleared after" || no "zovl: node B: $(echo "$log" | grep -a 'node B' | tail -2)"
echo "$log" | grep -aq '^zovl: the data after the last node read through the overlay handle' && echo "$log" | grep -aq '^zovl: memory as before' && echo "$log" | grep -aq '^zovl-rc=0' && ok "zovl: the data after the nodes read through the overlay handle, memory as before, return code 0" || no "zovl: the end: $(echo "$log" | grep -a 'zovl' | tail -3)"
echo "$log" | grep -aq '^ZINE: zovl is damaged (no overlay part where its overlay table points) (the overlay part at byte [0-9]*)' && echo "$log" | grep -aq 'zovl crashed (alert 0700000c: its overlay supervisor could not load a part)' && echo "$log" | grep -aq '^zovlbad-rc=1' && ok "zovl bad: LoadSeg's refusal named, the supervisor's AN_BadOverlay ends it, Zenix back" || no "zovl bad: $(echo "$log" | grep -a 'zovl' | tail -3)"
# 16.7: a cruncher's data after its overlay table (Spaceballs' Peek's form), read with packets the program sends to its
# overlay handle's fh_Type itself; a packet to Output()'s; dos Execute answered done, not run; a dos call ZINE lacks
# shows its first argument's text
echo "$log" | grep -aq '^ZINE: zpkt keeps 1 KB of data after its overlay table and reads it itself through its overlay file' && ok "zpkt: zine's line for an overlay table with data and no parts" || no "zpkt: zine's line: $(echo "$log" | grep -a 'ZINE: zpkt' | head -1)"
echo "$log" | grep -aq "^zpkt: the data after the overlay table read with packets to the overlay handle's handler port" && echo "$log" | grep -aq '^ZINE: a packet of type 9999 sent to a file.s handler, which ZINE does not know: answered with an error' && ok "zpkt: ACTION_SEEK from the end, ACTION_READ, ACTION_FLUSH answered through fh_Type, an unknown action refused and named" || no "zpkt: the packets: $(echo "$log" | grep -a 'zpkt' | tail -3)"
echo "$log" | grep -aq "^zpkt: written with a packet to Output()'s handler port" && ok "zpkt: ACTION_WRITE to Output()'s handler port" || no "zpkt: the written packet"
echo "$log" | grep -aq '^ZINE: zpkt asked dos Execute to run "run >nil: setpatch": not run (ZINE has no shell), answered as done' && echo "$log" | grep -aq '^zpkt: Execute answered done' && echo "$log" | grep -aq '^zpkt-rc=0' && ok "zpkt: Execute named, not run, answered DOSTRUE; return code 0" || no "zpkt: Execute: $(echo "$log" | grep -a 'Execute\|zpkt-rc' | tail -2)"
echo "$log" | grep -aq '^ZINE: the call.s first argument (d1) reads "RAM:zpkt-gone"' && echo "$log" | grep -aq 'zpkt called dos.library Rename (offset -78, from' && echo "$log" | grep -aq '^zpktu-rc=1' && ok "zpkt u: a dos call ZINE lacks named with its first argument's text" || no "zpkt u: $(echo "$log" | grep -a 'Rename\|first argument\|zpktu' | tail -3)"
# 16.12: the Top 100's fixes: the cruncher's overlay form (two hunks listed, one before HUNK_OVERLAY: Love,
# Boogietown), SuperState/UserState, the calls the productions asked for, a Latin-1 file name that is not UTF-8
echo "$log" | grep -aq '^ZINE: zcrunch keeps 1 KB of data after its overlay table' && echo "$log" | grep -aq '^zcrunch-rc=0' && ok "zcrunch: the cruncher's overlay form (two hunks listed, the second empty) loaded; its data read with packets; return code 0" || no "zcrunch: $(echo "$log" | grep -a 'zcrunch' | tail -2)"
echo "$log" | grep -aq "^zsuper: SuperState and UserState on the program's own stack; the user vectors low; an interrupt with ExecBase written over acknowledged" && echo "$log" | grep -aq '^zsuper-rc=0' && ok "zsuper: SuperState (supervisor mode, the same stack, the system stack in d0; 0 when already there) and UserState; the user vectors 64-255 at a low stub (no 68010 bit at 297 through a base of 0, 16.22); with ExecBase written over a SOFTINT acknowledged, nothing called through it (16.23)" || no "zsuper: $(echo "$log" | grep -a 'zsuper' | tail -2)"
zc() { echo "$log" | grep -aq "$1"; }
zc '^zcalls-raw: RawPutChar on the serial port' && zc "^zcalls: exec's IO requests, public ports and debug serial port answered" && ok "zcalls: CreateIORequest/DeleteIORequest, AddPort/FindPort/RemPort, RawIOInit/RawMayGetChar, RawPutChar on the serial line" || no "zcalls exec: $(echo "$log" | grep -a 'zcalls' | head -3)"
zc '^zcalls: FWrite in two blocks.$' && zc '^zcalls: IsInteractive, FWrite, GetProgramName, ReadArgs answered' && ok "zcalls: IsInteractive, FWrite, GetProgramName, ReadArgs of FROM/A,TO/K,N=NUM/N,Q=QUIET/S,REST/M and a missing /A (116), AllocDosObject" || no "zcalls dos: $(echo "$log" | grep -a 'zcalls' | tail -3)"
zc '^ZINE: no font "nosuch.font"' && zc '^zcalls: topaz 8 drew an A; GetBitMapAttr, SetChipRev, BestModeIDA answered' && ok "zcalls: OpenFont topaz 8 (another name said and 0), Text drew A's rows, TextLength, GetBitMapAttr, SetChipRev (\$1F on AGA, 16.20), BestModeIDA" || no "zcalls graphics: $(echo "$log" | grep -a 'zcalls\|font' | tail -3)"
zc '^zcalls: the public screen and screen buffers answered' && zc "^zcalls: utility.library's tags, division, multiply, Stricmp and dates answered" && zc '^zcalls: the six math libraries computed' && zc '^zcalls-rc=0' && ok "zcalls: LockPubScreen, the screen buffers; utility.library; the six math libraries; return code 0" || no "zcalls: the rest: $(echo "$log" | grep -a 'zcalls' | tail -3)"
zc '^ZINE: zbig is loaded from its file now' && zc '^zbig: loaded from its file before the hand-over: its chip, fast and BSS hunks right' && ok "zbig: a program whose file and hunks do not fit together loaded by zine from its file (chip, fast and BSS hunks, relocations)" || no "zbig: the load: $(echo "$log" | grep -a 'zbig' | head -4)"
zc '^ZINE: zlean is loaded from its file now; its file (420 KB) is not kept' && zc '^zlean-rc=0' && ok "zlean: a big plain program's file not kept, its fast hunk loaded from the file below 16 MB (16.18, 16.19)" || no "zlean: $(echo "$log" | grep -a 'zlean' | tail -3)"
# 16.23: zbig.huge (400 KB) stays on the disk and is read from there during the session; with -m (every file in memory)
# the folder is too big for the volume as before
zbd=$(echo "$log" | grep -a "^ZINE: [0-9]* of zbig's files ([0-9]* KB) stay on the disk" | head -1 | cut -d' ' -f2)
[ -n "$zbd" ] && [ "$zbd" -ge 2 ] && zc "^zine: zbig's directory holds" && zc '^zbig: zbig.small found; zbig.huge read from the disk (its first longword, 1 KB, across sectors, the last bytes, the end, 100 KB across runs) right; zbig.mid1 and .mid6 right; zbig-pack.lha left out' && zc '^zbig-rc=0' && ok "zbig: a big data file read from the disk during the session (16.23): its first longword, an aligned 1 KB straight into the buffer, 8 bytes through the sector cache, 8 across a sector's end, the last 8 from the end, then the end, 100 KB in one read past the 12th block; the folder over the volume's budget: $zbd files on the disk, the 60 KB ones it would leave out among them, read right, the archive left out; return code 0" || no "zbig: from the disk: $(echo "$log" | grep -a 'zbig' | tail -4)"
zc '^zine: zbig-pack.lha left out (41 KB): an archive or a disk image' && zc '^zine: and [0-9]* more files left out' && zc '^zbig: zbig.small found; zbig.huge and zbig-pack.lha left out of the volume' && zc '^zbigm-rc=0' && ok "zbig -m: every file in memory: a folder too big for the volume: the archive, then the largest files left out and named; the small file found; return code 0" || no "zbig -m: the volume: $(echo "$log" | grep -a 'zbig' | tail -4)"
# 16.23: zine -c, chip RAM only (as NoFastMem): the program sees no fast RAM and runs
zc '^ZINE: zhello sees chip RAM only (-c)' && zc '^ZINE: zhello had [0-9]* KB chip and 0 KB fast RAM' && zc '^zhelloc-rc=0' && ok "zhello -c: chip RAM only (16.23): no fast RAM in its memory lists, its hunks in chip RAM; return code 0" || no "zhello -c: $(echo "$log" | grep -a 'zhello' | tail -3)"
zc '^hello from an AmigaOS program' && zc '^zlatin-rc=0' && ok "a program whose file name is Latin-1 (not UTF-8) on the Zenix disk runs" || no "the Latin-1 name: $(echo "$log" | grep -a 'zlatin\|AmigaDOS name' | tail -2)"
# 16.13: the third Top 100 round (znext.S, run by tools/tests/zine/zfix17): the calls, and diskfont on the test fonts
zc '^znext: exec.s Allocate, Deallocate and FindSemaphore answered' && ok "znext: Allocate/Deallocate on a MemHeader of its own (8-byte blocks, a freed block reused, too big 0), FindSemaphore" || no "znext exec: $(echo "$log" | grep -a 'znext' | head -3)"
zc '^znext: Lock, Examine, ExNext, NameFromLock, ParentDir, CurrentDir and DateStamp answered' && zc '^ZINE: znext asks for the volume ZDisk:, which ZINE takes as the program.s own folder' && ok "znext: Lock/Examine of Data/Sub/f.txt, ExNext of DATA (Sub, then 232), NameFromLock ZINE:Data, ParentDir the top, CurrentDir (Sub/f.txt read, /znext found), a missing Lock 205, DateStamp; ZDisk:Data/Sub/f.txt found in its folder (said), T:znext not" || no "znext dos: $(echo "$log" | grep -a 'znext' | tail -3)"
zc '^znext: GetVPModeID, ModeNotAvailable, VideoControl, QueryOverscan, BltClear, sprites, Draw, DrawBorder answered' && ok "znext: GetVPModeID \$29000, ModeNotAvailable, VideoControl's tags, ScrollVPort/RethinkDisplay/MakeScreen/MoveScreen, QueryOverscan's rectangles, BltClear, GetSprite/FreeSprite, Draw/DrawBorder/PolyDraw pixels" || no "znext graphics: $(echo "$log" | grep -a 'znext' | tail -3)"
zc '^ZINE: the program asks (a requester) "ZNext": Pick one \[Yes|No\]: answered with the leftmost gadget' && zc '^ZINE: the program shows an alert: ZNEXT ALERT (answered with the right mouse button: FALSE)' && zc "^znext: intuition's Remember lists, requester and alert answered" && ok "znext: AllocRemember/FreeRemember (memory back), EasyRequestArgs said and answered 1 (one gadget: 0), DisplayAlert said and FALSE, WBenchToFront FALSE" || no "znext intuition: $(echo "$log" | grep -a 'znext\|requester\|alert' | tail -3)"
zc '^ZINE: znext needs nosuch.font size 8: copy it into /usr/share/fonts/amiga' && zc '^ZINE: znext: the font zbad.font size 11 cannot be used: FONTS:zbad/11 is damaged (' && zc '^ZINE: znext: ztest.font size 12 is not there (11 are): size 11 given instead' && zc '^ZINE: znext needs ztest.font size 12: FONTS:ztest.font has sizes 11 only' && ok "znext: diskfont: a missing font named with where to put it; a damaged one refused with its reason; a size it lacks: the nearest given and said, FPF_DESIGNED refused" || no "znext fonts said: $(echo "$log" | grep -a 'font' | tail -4)"
zc '^znext: the second batch (pixels, ColorMaps, a View of its own, DBufInfo, FilePart, Fault, timer units) answered' && zc '^znext: no more entries in directory' && ok "znext: WritePixel/ReadPixel, GetColorMap/SetRGB4CM/GetRGB4/GetRGB32, a View of its own (InitView, InitVPort, LoadView, MrgCop, WaitBOVP), AllocDBufInfo/ChangeVPBitMap, FilePart/PathPart/AddPart, Fault and PrintFault, SumKickData, timer.device's UNIT_WAITECLOCK (an E-clock time 0.1 s ahead: 0.05-1 s)" || no "znext second batch: $(echo "$log" | grep -a 'znext' | tail -3)"
zc '^znext: the DOS list, GetDeviceProc, DoPkt, 40 open files, CompareDates, CopyMem and RectFill answered' && ok "znext: LockDosList, NextDosEntry (the volume ZINE, then the RAM device), FindDosEntry without case, UnLockDosList; GetDeviceProc (the handler port, the volume's node; a second call 0), FreeDeviceProc; DoPkt to the handler port (ACTION_IS_FILESYSTEM, ACTION_DISK_INFO) and to a non-port (DOSFALSE, error 209; 16.19); 40 files open at once (16.19); CompareDates in the manual's order; CopyMem of 45 bytes from and to odd addresses; RectFill set and complemented byte-wise (16.18)" || no "znext dos list: $(echo "$log" | grep -a 'znext' | tail -3)"
zc "^znext: diskfont opened fonts from FONTS: and the program's own folder; AvailFonts listed them" && zc '^znext-rc=0' && ok "znext: OpenDiskFont ztest 11 from /usr/share/fonts/amiga (proportional widths), zfixed 9 from the program's own Fonts folder, OpenFont finds a loaded one, AvailFonts; return code 0" || no "znext: the end: $(echo "$log" | grep -a 'znext' | tail -3)"
# 16.16: more than one task (ztask.S, zsound.S)
zc '^ztask: all 9 parts right' && zc '^ztask-rc=0' && ok "ztask: a child of higher priority runs at once, 100 signals ping-ponged with a switch at each, 10 messages and ReplyMsg, preemption from a vertical blank server, the quantum among equals, Forbid holding the task, a semaphore waited for, AddTask/RemTask, dos Exit with its exit hook; every child gone" || no "ztask: $(echo "$log" | grep -a 'ztask' | tail -3)"
zc '^zsound: played and drew' && zc '^zsound-rc=0' && ok "zsound: a CreateNewProc process played eight double-buffered audio.device writes (channel 0's DMA on, in order, about their length) while the first task drew with WaitTOF" || no "zsound: $(echo "$log" | grep -a 'zsound' | tail -3)"
# 16.8: Ltx-Snigelsaft's sequence with a library of ZINE's own: written to RAM:, Execute "Ram:Assign LIBS: Ram:" done
# by ZINE, OpenLibrary loading it from RAM: (RomTag, auto-init), its functions, CloseLibrary, LIBS: back, DeleteFile;
# semaphores, audio.device's channels, Paula's and CIA-B's interrupts as a SID player uses them; memory as before
zl() { echo "$log" | grep -aq "$1"; }
zl '^zlibs: the library written to RAM: and read back' && ok "zlibs: a file written to RAM: and read back" || no "zlibs: RAM: $(echo "$log" | grep -a 'zlibs' | tail -2)"
zl '^ZINE: zlibs asked dos Execute to run "Assign LIBS: SYS:LIBS": done by ZINE itself (LIBS: is now SYS:LIBS)' && zl '^ZINE: no library zt.library' && ok "zlibs: Execute \"Assign LIBS: SYS:LIBS\" done by ZINE; zt.library not found there" || no "zlibs: the first assign: $(echo "$log" | grep -a 'Assign\|no library' | head -3)"
zl '^ZINE: zlibs asked dos Execute to run "Ram:Assign LIBS: Ram:": done by ZINE itself (LIBS: is now Ram:)' && zl '^ZINE: zt.library (version 3) loaded from Ram:zt.library' && zl '^zlibs: zt.library opened from RAM:' && ok "zlibs: \"Ram:Assign LIBS: Ram:\", OpenLibrary loaded zt.library from RAM: (RomTag, MakeLibrary, InitStruct, init, Open) and its functions answered" || no "zlibs: the library from RAM: $(echo "$log" | grep -a 'zt.library\|Ram:Assign' | head -3)"
zl '^ZINE: zt.library is version 3, the program asks for version 4' && ok "zlibs: a newer version asked for: refused, said" || no "zlibs: the version line"
zl '^ZINE: zlibs asked dos Execute to run "C:Assign LIBS: SYS:LIBS/": done by ZINE itself (LIBS: is now SYS:LIBS/)' && zl '^zlibs: the file deleted from RAM:, gone' && ok "zlibs: LIBS: back, DeleteFile of the RAM: file, a second delete ERROR_OBJECT_NOT_FOUND" || no "zlibs: the delete: $(echo "$log" | grep -a 'zlibs' | tail -2)"
zl '^zlibs: still loaded after the delete; RemLibrary expunged it' && ok "zlibs: the library stays loaded after the delete; RemLibrary runs its Expunge, its segments unloaded" || no "zlibs: the expunge"
zl '^zlibs: audio.device gave the four channels' && ok "zlibs: semaphores; audio.device's channels allocated, a second request and its CMD_WRITE refused (ADIOERR_NOALLOCATION: not its channels; d29 16.16)" || no "zlibs: audio.device: $(echo "$log" | grep -a 'zlibs\|audio' | tail -2)"
zl "^zlibs: Paula's channel 0 interrupt through SetIntVector" && zl '^zlibs: CIA-B timer A through ciab.resource' && ok "zlibs: Paula's level 4 interrupt (SetIntVector) and CIA-B timer A (ciab.resource) delivered" || no "zlibs: the interrupts: $(echo "$log" | grep -a 'zlibs' | tail -2)"
zl "^zlibs: the CIA resources found through ExecBase's chains, a handler written into the vector called" && ok "zlibs: the CIA resources as Loonies' replayer finds them (16.20): the first node of the EXTER and PORTS chains 42 bytes into ciab/ciaa.resource, the in-use mask 40 bytes in, a handler written into timer A's vector (68 bytes in) called by the interrupt, the old one not" || no "zlibs: the CIA resources' private fields: $(echo "$log" | grep -a 'zlibs' | tail -2)"
zl '^zlibs: memory as at the start' && zl '^zlibs-rc=0' && ok "zlibs: AvailMem as at the start, return code 0" || no "zlibs: the end: $(echo "$log" | grep -a 'zlibs' | tail -3)"
# 16.9: a write to any path kept in memory for the session (zwrite.S), the disk untouched
zl '^zwrite: T:, ENV:, the program.s folder and DH0: written and read back from memory' && ok "zwrite: T:, ENV:, PROGDIR: and DH0: files written and read back by other forms of their paths; NIL: keeps nothing" || no "zwrite: the paths: $(echo "$log" | grep -a 'zwrite' | tail -2)"
zl '^zwrite: its own zexit shadowed by what it wrote' && zl '^zwrite: zhello changed through MODE_READWRITE, a copy in memory' && ok "zwrite: a file of its own folder shadowed by a written one; MODE_READWRITE changes a copy in memory" || no "zwrite: the shadow: $(echo "$log" | grep -a 'zwrite' | tail -2)"
zl '^zwrite: the deleted files are gone for the session' && zl '^zwrite-rc=0' && ok "zwrite: DeleteFile of a shadowed, an unwritten and a T: file: not found afterwards, a second delete ERROR_OBJECT_NOT_FOUND; return code 0" || no "zwrite: the deletes: $(echo "$log" | grep -a 'zwrite' | tail -3)"
zl '^zwrite: SetProtection, SetComment and SetFileDate answer' && ok "zwrite: SetProtection, SetComment, SetFileDate: DOSTRUE for a written file, one of its own; ERROR_OBJECT_NOT_FOUND for a deleted one (16.24)" || no "zwrite: the attributes: $(echo "$log" | grep -a 'zwrite' | tail -3)"
zl '^zwrite: FGetC, UnGetC and FGets read zw.new a line at a time' && ok "zwrite: FGetC, UnGetC (the byte again) and FGets (a line, then 0 at the end) (16.24)" || no "zwrite: FGetC/FGets: $(echo "$log" | grep -a 'zwrite' | tail -3)"
zl '^zwdisk-same' && ok "zwrite: the disk afterwards as before (zexit, zhello, zbadcall the same bytes; no zw.new, zw or T written)" || no "zwrite: the disk changed after the session"
# 16.10: names found without case, in subdirectories of the program's folder (zcase.S)
zl '^zcase: files in subdirectories found by names of another case' && ok "zcase: DATA/Xyl.Tp3, PROGDIR:data/xyl.tp3 and SYS:data/deep/er/mod.x found (Data/XYL.TP3, three levels down)" || no "zcase: the subdirectories: $(echo "$log" | grep -a 'zcase\|no file' | tail -2)"
zl '^ZINE: Data/clash and Data/CLASH differ only in case, which AmigaDOS does not tell apart: a name the program uses finds the one spelt exactly so, else Data/clash' && zl '^zcase: two names the same but for case: the exact one, else the first found' && ok "zcase: Data/clash and Data/CLASH: said once; each found by its exact name, Data/Clash the first found" || no "zcase: the twins: $(echo "$log" | grep -a 'zcase\|differ only' | tail -2)"
zl '^ZINE: zt.library (version 3) loaded from SYS:LIBS/zt.library' && zl '^zcase: LoadSeg and OpenLibrary from LIBS: by names of another case' && ok "zcase: LoadSeg of data/DEEP/er/ZEXIT; OpenLibrary loaded zt.library from the folder's LIBS/ZT.Library" || no "zcase: LoadSeg, OpenLibrary: $(echo "$log" | grep -a 'zcase\|zt.library' | tail -2)"
zl '^zcase: written, shadowed and deleted by names of another case' && zl '^zcase-rc=0' && ok "zcase: data/NEW.txt read back as DATA/new.TXT; DATA/xyl.TP3 written over the folder's file, read back as Data/XYL.TP3, deleted as data/Xyl.tp3; return code 0" || no "zcase: the writes: $(echo "$log" | grep -a 'zcase' | tail -3)"
zl '^CLASH Deep XYL.TP3 clash zcase-ls' && echo "$log" | grep -a -B2 '^CLASH Deep XYL.TP3' | grep -aq '^upper' && ok "zcase: the folder afterwards as before (Data/XYL.TP3 still \"upper\", no NEW.txt)" || no "zcase: the folder changed: $(echo "$log" | grep -a -B2 'zcase-ls' | head -3)"
# 16.11: a demo made of separate programs (Spaceballs' HOG): dos Execute runs a command that names a program file
# (zexec.S runs zpart.S: in its folder, in a subfolder, nested, to ZINE's limit)
zl '^ZINE: zexec asked dos Execute to run "zpart >NIL: one  "two words"  ": runs zpart$' && zl '^ZINE: the command zpart ended with return code 5; zexec goes on' && zl '^zexec: part one ran with its arguments, its output to NIL:, return code 5' && ! zl 'must not be seen' && ok "zexec: a part run for real with its argument line (a0/d0, ending in a newline), its stack from its \$STACK: cookie, cli_Module; >NIL: took its output; return code 5 as IoErr() and cli_ReturnCode" || no "zexec: part one: $(echo "$log" | grep -a 'zexec\|zpart' | head -4)"
zl '^ZINE: zexec asked dos Execute to run "parts/SECOND two": runs parts/SECOND' && zl '^zpart: two ran from its subfolder, PROGDIR:here its own; its command name: parts/SECOND$' && ok "zexec: a part in a subfolder named in another case; PROGDIR: its own folder, cli_CommandName as given" || no "zexec: the subfolder part: $(echo "$log" | grep -a 'SECOND\|zpart: two\|zpart: failed' | head -3)"
zl '^ZINE: zpart asked dos Execute to run "run >NIL: zpart deep": runs zpart (after run, but to its end before the program goes on: ZINE runs one task)' && zl '^ZINE: the command zpart ended with return code 7; zpart goes on' && zl '^zpart: the nested part ended with Exit(7)' && zl '^zexec: the nested parts ran, return code 3' && ok "zexec: a part that Executes \"run >NIL: zpart deep\" (run synchronously, said); dos Exit(7) ends only the nested part" || no "zexec: nested: $(echo "$log" | grep -a 'deep\|nest' | head -3)"
nl=$(echo "$log" | grep -ac '^zpart: the ninth loop refused at ZINE.s limit')
zl '^ZINE: zpart asked dos Execute to run "zpart loop": ZINE runs at most 8 commands inside one another, answered as failed' && [ "$nl" = 1 ] && ok "zexec: parts inside parts: 8 run, the ninth refused (DOSFALSE), said once" || no "zexec: the limit ($nl refusals): $(echo "$log" | grep -a 'at most 8\|ninth' | head -2)"
zl '^ZINE: zexec asked dos Execute to run "nosuchpart x": no program nosuchpart in its folder or C: (a Shell says "nosuchpart: Unknown command"), answered as failed' && zl '^zexec: a missing part answered DOSFALSE, ERROR_OBJECT_NOT_FOUND' && ok "zexec: a name that is no program: said, DOSFALSE and ERROR_OBJECT_NOT_FOUND" || no "zexec: the missing part: $(echo "$log" | grep -a 'nosuchpart\|missing' | head -2)"
zl '^ZINE: zexec asked dos Execute to run "zpart hand": runs zpart$' && zl '^zpart: its segments handed over in cli_Module, a 64 KB segment first$' && ok "zexec: a part that hands its segments over in cli_Module, as a decruncher (CrunchMania) does, ran" || no "zexec: the hand-over: $(echo "$log" | grep -a 'hand' | head -3)"
zl '^ZINE: zexec asked dos Execute to run "stack 20000": not run (ZINE has no shell), answered as done' && zl '^zexec: memory as at the start' && zl '^zexec-rc=0' && ok "zexec: a Shell command not run, answered as done; every part's segments, stack and files freed (AvailMem as at the start; the hand-over's: the list in cli_Module when it ended, as the Shell unloads it); return code 0" || no "zexec: the end: $(echo "$log" | grep -a 'zexec' | tail -3)"
# (a kernel log line may land inside the zbg line: the count and the last line are checked apart)
echo "$log" | grep -aq '^zbg=400' && echo "$log" | grep -aq 'last=399$' && ok "a background job writing a file during a session: its requests held at the sync and done afterwards, none lost" || no "the held writes: $(echo "$log" | grep -a '^zbg=' | tail -1)"
# 16.5: a 68030 MMU instruction on a CPU without that MMU (the 68020 here) is a no-op; an FPU instruction this machine
# lacks (no FPU here) is named in the crash line
echo "$log" | grep -aq '^zmmu-rc=0' && echo "$log" | grep -aq 'ZINE: an MMU instruction (PMOVE, PFLUSH, PTEST) taken as a no-op' && ok "zmmu: PMOVE to and from TC, TT0, CRP, SRP (memory, (An)+, -(sp), d16(An), #imm), PFLUSHA, and in supervisor mode the 68040's PFLUSHA and PMOVE TC, as no-ops on a 68020" || no "zmmu: $(echo "$log" | grep -a 'zmmu\|MMU instruction' | tail -2)"
echo "$log" | grep -aq 'zfpu crashed: line F instruction at .* (instruction f200 000e: FSIN, ' && echo "$log" | grep -aq '^zfpu-rc=1' && ok "zfpu: FSIN without an FPU: the crash line names it" || no "zfpu: $(echo "$log" | grep -a 'zfpu' | tail -2)"
# D29 12.1: an executable AmigaOS program runs by its name (the kernel runs /bin/zine PATH ARGS); without x it does not
echo "$log" | grep -aq '^byname1=7' && ok "an AmigaOS program run by its path (/tmp/zx/zexit a b: through zine, return code 7)" || no "by path: $(echo "$log" | grep -a 'byname1' | tail -1)"
echo "$log" | grep -aq '^byname2=7' && ok "an AmigaOS program run as ./zexit" || no "./zexit: $(echo "$log" | grep -a 'byname2' | tail -1)"
echo "$log" | grep -aq '^byname3=7' && ok "an AmigaOS program found on PATH" || no "on PATH: $(echo "$log" | grep -a 'byname3' | tail -1)"
echo "$log" | grep -aq '^byname4=126' && ok "an AmigaOS program without the x bit is not run by name" || no "without x: $(echo "$log" | grep -a 'byname4' | tail -1)"
f3=$(echo "$log" | grep -a '^fast RAM free' | tail -1 | tr -dc 0-9); c3=$(echo "$log" | grep -a '^chip RAM free' | tail -1 | tr -dc 0-9)
# the mark: taken after the files above are written, just before the real programs (they stay in the RAM disk)
f1=$(echo "$log" | grep -a '^fast RAM free' | sed -n 3p | tr -dc 0-9); c1=$(echo "$log" | grep -a '^chip RAM free' | sed -n 3p | tr -dc 0-9)
[ "$f3" = "$f1" ] && [ "$c3" = "$c1" ] && ok "free memory after the real programs as before them" || no "free memory after the real programs: chip $c3 KB, fast $f3 KB (before: $c1, $f1)"
echo "$log" | grep -aq '^zgroup1=1' && echo "$log" | grep -aq 'zine: not allowed: root and the members of the group zine' && ok "a user outside the group zine is refused" || no "zine group, outside: $(echo "$log" | grep -a 'zgroup1\|group zine' | tail -2)"
echo "$log" | grep -aq '^zgroup2=7' && ok "after gpasswd -a user zine the user runs zine (set-user-id root, the group checked by zine)" || no "zine group, member: $(echo "$log" | grep -a 'zgroup2' | tail -2)"
echo "$log" | grep -aq '^zgroup3=7' && ok "zine reads a 640 program of the group zine for a user in it as a supplementary group" || no "zine group, a group-readable program: $(echo "$log" | grep -a 'zgroup3' | tail -1)"
echo "$log" | grep -aq '^zgroup4=1' && ok "zine refuses a 640 program of root's group to that user (it reads only what the user may)" || no "zine group, root's group: $(echo "$log" | grep -a 'zgroup4' | tail -1)"
echo "$log" | grep -aq '^zine-null-done' || no "the script did not reach its end"
# 16.4/16.5 on a 68040 with its FPU (the matrix's A1200 040 with FS-UAE's 68040 FPU, fsuae/zine): the MMU's registers
# saved and put back around each session, the 68030 MMU instructions as no-ops; 16.14: FSIN and zfpux's 36 other
# instructions the 040 lacks (as a real one) emulated by Motorola's package (/lib/zine/sp040), every answer right
L4=$OUT/serial-040.log
ZENIX_BUILD=$BD tools/run-test.sh fsuae/zine/a1200-040fpu.fs-uae 300 tools/tests/zine-040-test.txt > $L4 2>&1
log4=$(tr -d '\r' < $L4)
echo "$log4" | grep -aq '^zmmu-rc=0' && echo "$log4" | grep -aq 'ZINE: an MMU instruction (PMOVE, PFLUSH, PTEST) taken as a no-op' && ok "68040: zmmu's 68030 MMU instructions as no-ops" || no "68040 zmmu: $(echo "$log4" | grep -a 'zmmu\|MMU instruction' | tail -2)"
echo "$log4" | grep -aq "^ZINE: the 68040's missing FPU instructions are emulated (Motorola's M68040 Floating Point Software Package)" && echo "$log4" | grep -aq '^zfpu-rc=0' && ok "68040: FSIN (the 040 lacks it) emulated by the 68040 package (16.14)" || no "68040 zfpu: $(echo "$log4" | grep -a 'zfpu\|sp040\|68040.s' | tail -2)"
echo "$log4" | grep -aq '^zfpux: all 37 answers right' && echo "$log4" | grep -aq '^zfpux-rc=0' && ok "68040: zfpux: FSIN ... FREM, FMOVECR, FSINCOS, packed decimal, a denormal, an immediate; MULU.L/DIVU.L 64, MOVEP, CAS2, CHK2: every answer right" || no "68040 zfpux: $(echo "$log4" | grep -a 'zfpux' | tail -3)"
echo "$log4" | grep -aq '^zcalls: the six math libraries computed' && echo "$log4" | grep -aq '^zcalls-rc=0' && ok "68040: zcalls' math libraries on the FPU (16.13: the soft-float calls wrapped), every answer as without one" || no "68040 zcalls: $(echo "$log4" | grep -a 'zcalls' | tail -2)"
echo "$log4" | grep -aq '^zcon: written through console.device$' && echo "$log4" | grep -aq '^ZINE: AllocMem of 1048576 KB refused: the largest free block is ' && echo "$log4" | grep -aq '^zcon: all answered' && echo "$log4" | grep -aq '^zcon-rc=0' && ok "zcon (16.14): console.device's CMD_WRITE in the output without its control sequences, a CMD_READ in progress until AbortIO, the ConUnit's 80 x 25 grid; input.device's handler added and removed; ViewAddress; a refused 1 GB AllocMem said" || no "zcon: $(echo "$log4" | grep -a 'zcon\|AllocMem of' | tail -3)"
# 16.15: a program that switches the 040's data cache on itself and writes chip RAM: the blitter sees the write
echo "$log4" | grep -aq '^zcache: all answered' && echo "$log4" | grep -aq '^zcache-rc=0' && ok "68040: zcache: the data cache switched on by the program, a chip RAM write seen by the blitter (DTT0 inhibits the first 16 MB); MOVEC CAAR a no-op; AttnFlags say the FPU; CacheControl keeps the data cache off ($(echo "$log4" | grep -a '^zcache: control' | sed 's/.*(//; s/)//'))" || no "68040 zcache: $(echo "$log4" | grep -a 'zcache\|CAAR' | tail -3)"
echo "$log4" | grep -aq '^ztake-rc=0' && echo "$log4" | grep -aq '^zcrash-rc=1' && ok "68040: ztake and zcrash, Zenix back each time (the MMU registers and caches restored)" || no "68040 ztake/zcrash: $(echo "$log4" | grep -a 'ztake-rc\|zcrash-rc' | tail -2)"
g1=$(echo "$log4" | grep -a -m1 '^fast RAM free' | tr -dc 0-9); g2=$(echo "$log4" | grep -a '^fast RAM free' | sed -n 2p | tr -dc 0-9)
[ -n "$g1" ] && [ "$g1" = "$g2" ] && echo "$log4" | grep -aq '^zine-040-done' && echo "$log4" | grep -aq '^disk-ok' && ok "68040: free memory as before, the disk written afterwards" || no "68040: memory $g1 -> $g2 KB, or the end not reached"
# D41 section 19: memory protection is on there by default (FS-UAE's MMU model): every session switched it off and back
# on (the kernel's 'back' lines), and after them a stray write is still stopped
prot() {    # prot NAME LOG
    echo "$2" | grep -aq "^mmu: memory protection on: $1" && echo "$2" | grep -aq '^prot-rc=139' &&
        echo "$2" | grep -aq 'memory protection: a write to 0x1000 (the kernel.s memory): killed' &&
        ok "$1: memory protection on at boot, and on again after the sessions (a stray write stopped, status 139)" ||
        no "$1 protection: $(echo "$2" | grep -a '^mmu:\|prot-rc\|memory protection' | tail -3)"
}
prot 68040 "$log4"
echo "$log4" | grep -aiE 'panic|exception|guru' && no "68040: the kernel log has a panic or exception"
