echo "$log6" | grep -aq '^zfpux: all 37 answers right' && echo "$log6" | grep -aq '^zfpux-rc=0' && ok "68060: zfpux: the 32 FPU answers and the 5 integer ones (MULU.L/DIVU.L 64, MOVEP, CAS2, CHK2) right" || no "68060 zfpux: $(echo "$log6" | grep -a 'zfpux' | tail -3)"
echo "$log6" | grep -aq '^zcrash-rc=1' && echo "$log6" | grep -aq '^zcalls-rc=0' && ok "68060: zcrash's crash named and zcalls' answers with the package in place" || no "68060 zcrash/zcalls: $(echo "$log6" | grep -a 'zcrash-rc\|zcalls-rc' | tail -2)"
# 16.15: the same on the 68060 (its EDC bit); a second process refused as AmigaOS refuses one (0, IoErr 103), said once
echo "$log6" | grep -aq '^zcache: all answered' && echo "$log6" | grep -aq '^zcache-rc=0' && echo "$log6" | grep -aq '^ZINE: a MOVEC to or from CAAR (68020/030 only) taken as a no-op on this CPU' && ok "68060: zcache: the data cache switched on by the program, a chip RAM write seen by the blitter; MOVEC CAAR a no-op, said; AttnFlags say the FPU; CacheControl keeps the data cache off ($(echo "$log6" | grep -a '^zcache: control' | sed 's/.*(//; s/)//'))" || no "68060 zcache: $(echo "$log6" | grep -a 'zcache\|CAAR' | tail -3)"
# 16.16: more than one task: the same on the 68060 (with the FPU's state kept per task)
echo "$log6" | grep -aq '^ztask: all 9 parts right' && echo "$log6" | grep -aq '^ztask: FP0 kept for each task' && echo "$log6" | grep -aq '^ztask-rc=0' && ok "68060: ztask: the nine parts as on the 68020, and FP0 kept for each task across 20 switches" || no "68060 ztask: $(echo "$log6" | grep -a 'ztask' | tail -3)"
echo "$log6" | grep -aq '^zsound: played and drew' && echo "$log6" | grep -aq '^zsound-rc=0' && ok "68060: zsound: a CreateNewProc process played eight audio.device writes while the first task drew" || no "68060 zsound: $(echo "$log6" | grep -a 'zsound' | tail -3)"
